            if let Some(step) = self.steps.get(*s) {
                if !step.only_environments.is_empty() {
                    if let Some(ref active_env) = options.active_environment {
                        if !step.only_environments.iter().any(|e| e == active_env) {
                            env_skipped.push(s.to_string());
                            return false;
