        let mut broken_step = make_step("broken", "echo main", vec![]);
        broken_step.before = vec!["exit 1".to_string()];
        broken_step.allow_failure = true;

        let mut steps = HashMap::new();
        steps.insert("broken".to_string(), broken_step);
        steps.insert(
            "healthy".to_string(),
            make_step(
                "healthy",
