        ui.set_prompt_response("steps", "bundler,cargo");

        let prompt = Prompt {
            key: "steps".to_string(),
            question: "Select steps".to_string(),
            prompt_type: PromptType::MultiSelect {
                options: vec![
                    PromptOption {
                        label: "Bundler".to_string(),
                        value: "bundler".to_string(),
                    },
                    PromptOption {
                        label: "Cargo".to_string(),
                        value: "cargo".to_string(),
                    },
