        let theme = BivvyTheme::new();
        println!("{}{}", prefix, theme.format_error(msg));
    }

    fn finish_skipped(&mut self, msg: &str) {
        let prefix = " ".repeat(self.indent);
        let theme = BivvyTheme::new();
        println!("{}{}", prefix, theme.format_skipped(msg));
    }

    fn output_callback(
        &self,
        _base_message: &str,
        indent: usize,
        _max_lines: usize,
    ) -> Option<crate::shell::OutputCallback> {
        if !self.verbose {
            return None;
        }
        let prefix = " ".repeat(indent);
        Some(Box::new(move |line: crate::shell::OutputLine| {
            let text = match &line {
                crate::shell::OutputLine::Stdout(s) => s.trim_end(),
                crate::shell::OutputLine::Stderr(s) => s.trim_end(),
            };
            if !text.is_empty() {
                println!("{prefix}{text}");
            }
        }))
    }
}

